module traffic_light_mealy (
    input logic clk,
    input logic rst_n,
    input logic pedestrian_req,
    output logic [1:0] lights,  // 00: Green, 01: Yellow, 10: Red
    output logic walk_signal
);

typedef enum logic [1:0] {GREEN, YELLOW, RED} state_t;
state_t state, next_state;

// State register
always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        state <= GREEN;
    else
        state <= next_state;
end

// Next state and output logic
always_comb begin
    next_state = state;
    lights = {2{1'b0}};
    walk_signal = 1'b0;

    case (state)
        GREEN: begin
            lights = 2'b00;  // Green
            if (pedestrian_req) begin
                next_state = YELLOW;
                walk_signal = 1'b1;  // Walk signal triggered immediately
            end
        end

        YELLOW: begin
            lights = 2'b01;  // Yellow
            // Count 3 cycles then change to red
            // (simplified - normally would have counter)
            next_state = RED;
        end

        RED: begin
            lights = 2'b10;  // Red
            // After pedestrian crossing time
            next_state = GREEN;
        end
    endcase
end

endmodule,"

module serial_adder_mealy (
    input logic clk,
    input logic rst_n,
    input logic a_bit,
    input logic b_bit,
    input logic valid,
    output logic sum_bit,
    output logic carry_out
);

typedef enum logic {C0, C1} state_t;
state_t state, next_state;

// State register
always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        state <= C0;
    else
        state <= next_state;
end

// Next state and output logic
always_comb begin
    next_state = state;
    sum_bit = 1'b0;
    carry_out = 1'b0;

    if (valid) begin
        case (state)
            C0: begin  // Carry = 0
                case ({a_bit, b_bit})
                    2'b00: begin
                        sum_bit = 1'b0;
                        next_state = C0;
                    end
                    2'b01, 2'b10: begin
                        sum_bit = 1'b1;
                        next_state = C0;
                    end
                    2'b11: begin
                        sum_bit = 1'b0;
                        next_state = C1;
                    end
                endcase
            end

            C1: begin  // Carry = 1
                case ({a_bit, b_bit})
                    2'b00: begin
                        sum_bit = 1'b1;
                        next_state = C0;
                    end
                    2'b01, 2'b10: begin
                        sum_bit = 1'b0;
                        next_state = C1;
                    end
                    2'b11: begin
                        sum_bit = 1'b1;
                        next_state = C1;
                    end
                endcase
            end
        endcase

        // Final carry out
        if (state == C1 && {a_bit, b_bit} != 2'b00)
            carry_out = 1'b1;
    end
end

endmodule,,INVALID_OUTPUT,0.48635387420654297,3270,1

module arbiter_mealy (
    input logic clk,
    input logic rst_n,
    input logic req1,
    input logic req2,
    output logic grant1,
    output logic grant2
);

typedef enum logic {IDLE, GRANT1, GRANT2} state_t;
state_t state, next_state;

// State register
always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        state <= IDLE;
    else
        state <= next_state;
end

// Next state and output logic
always_comb begin
    next_state = state;
    grant1 = 1'b0;
    grant2 = 1'b0;

    case (state)
        IDLE: begin
            if (req1) begin
                next_state = GRANT1;
                grant1 = 1'b1;  // Grant immediately
            end
            else if (req2) begin
                next_state = GRANT2;
                grant2 = 1'b1;  // Grant immediately
            end
        end

        GRANT1: begin
            if (!req1) begin
                next_state = IDLE;
            end
            else if (req2) begin
                grant1 = 1'b1;  // Keep grant while req1 still high
            end
        end

        GRANT2: begin
            if (!req2) begin
                next_state = IDLE;
            end
            else if (req1) begin
                grant2 = 1'b1;  // Keep grant while req2 still high
            end
        end
    endcase
end

endmodule,"

module counter_2bit_mealy (
    input logic clk,
    input logic rst_n,
    input logic enable,
    output logic [1:0] count,
    output logic overflow
);

typedef enum logic [1:0] {C0, C1, C2, C3} state_t;
state_t state, next_state;

// State register
always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        state <= C0;
    else
        state <= next_state;
end

// Output logic for current count
assign count = state;

// Next state and overflow detection
always_comb begin
    next_state = state;
    overflow = 1'b0;

    if (enable) begin
        case (state)
            C0: next_state = C1;
            C1: next_state = C2;
            C2: next_state = C3;
            C3: begin
                next_state = C0;
                overflow = 1'b1;  // Overflow on transition
            end
        endcase
    end
end

endmodule,,INVALID_OUTPUT,2.2958078384399414,3025,1

module parity_checker_mealy (
    input logic clk,
    input logic rst_n,
    input logic din,
    input logic valid,
    output logic error
);

typedef enum logic {EVEN, ODD} state_t;
state_t state, next_state;

// State register
always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        state <= EVEN;
    else
        state <= next_state;
end

// Next state and output logic
always_comb begin
    next_state = state;
    error = 1'b0;

    if (valid) begin
        case (state)
            EVEN: begin
                if (din) begin
                    next_state = ODD;
                end
                // Error detection on final valid
                error = 1'b0;  // Even parity with even bits is OK
            end

            ODD: begin
                if (!din) begin
                    next_state = EVEN;
                end
                // Error detection on final valid
                error = 1'b1;  // Odd parity with odd bits is error
            end
        endcase
    end
end

endmodule,,INVALID_OUTPUT,0.2892768383026123,3025,1

module binary_to_bcd_mealy (
    input logic clk,
    input logic rst_n,
    input logic [7:0] binary_in,
    input logic convert,
    output logic [3:0] bcd_out,
    output logic bcd_valid
);

typedef enum logic [2:0] {IDLE, SHIFT, ADD3, DONE} state_t;
state_t state, next_state;
logic [7:0] binary_reg;
logic [11:0] bcd_reg;
logic [2:0] bit_count;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        binary_reg <= 8'b0;
        bcd_reg <= 12'b0;
        bit_count <= 3'b0;
    end else begin
        state <= next_state;
        if (state == SHIFT) begin
            binary_reg <= {binary_reg[6:0], 1'b0};
            bcd_reg <= {bcd_reg[10:0], binary_reg[7]};
            bit_count <= bit_count + 1;
        end
        if (state == ADD3)
            // Add 3 to each BCD digit > 4
            bcd_reg <= bcd_reg;
    end
end

always_comb begin
    next_state = state;
    bcd_out = 4'b0;
    bcd_valid = 1'b0;

    case (state)
        IDLE: begin
            if (convert) begin
                next_state = SHIFT;
                binary_reg = binary_in;
                bcd_reg = 12'b0;
                bit_count = 3'b0;
            end
        end

        SHIFT: begin
            if (bit_count == 3'b111) begin
                next_state = DONE;
                // Output on last shift
