    next_state = state;
    runt_detected = 1'b0;

    case (state)
        IDLE: begin
            if (signal_in)
                next_state = PULSE_HIGH;
            else
                next_state = PULSE_LOW;
        end

        PULSE_HIGH: begin
            if (!signal_in) begin
                next_state = CHECK;
                // Check if pulse was too short
                if (pulse_width < min_width)
